898:  *                          name will be returned in *pTexture.
899:  * @param[out] pTarget      @p *pTarget is set to the texture target used. The
900:  *                          target is chosen based on the file contents.
901:  * @param[out] pGlerror     @p *pGlerror is set to the value returned by
902:  *                          glGetError when this function returns the error
903:  *                          KTX_GL_ERROR. pGlerror can be NULL.
904:  *
905:  * @return  KTX\_SUCCESS on success, other KTX\_\* enum values on error.
906:  *
907:  * @exception KTX_GL_ERROR    A GL error was raised by glBindTexture,
908:  *                            glGenTextures or gl*TexImage*. The GL error
909:  *                            will be returned in @p *glerror, if glerror
910:  *                            is not @c NULL.
911:  * @exception KTX_INVALID_VALUE @p This or @p target is @c NULL or the size of
912:  *                              a mip level is greater than the size of the
913:  *                              preceding level.
914:  * @exception KTX_NOT_FOUND   A dynamically loaded OpenGL {,ES} function
915:  *                            required by the loader was not found.
916:  * @exception KTX_UNSUPPORTED_TEXTURE_TYPE The type of texture is not supported
917:  *                                         by the current OpenGL context.
918:  */
919: KTX_error_code
920: ktxTexture1_GLUpload(ktxTexture1* This, GLuint* pTexture, GLenum* pTarget,
921:                      GLenum* pGlerror)
922: {
923:     GLint                 previousUnpackAlignment;
924:     KTX_error_code        result = KTX_SUCCESS;
925:     ktx_glformatinfo      formatInfo;
926: 
927:     if (!This) {
928:         return KTX_INVALID_VALUE;
929:     }
930: 
931:     if (!pTarget) {
932:         return KTX_INVALID_VALUE;
933:     }
934: 
935:     result = ktxLoadOpenGL(NULL);
936:     if (result != KTX_SUCCESS) {
937:         return result;
