940:     glGetIntegerv(GL_UNPACK_ALIGNMENT, &previousUnpackAlignment);
941:     if (previousUnpackAlignment != KTX_GL_UNPACK_ALIGNMENT) {
942:         glPixelStorei(GL_UNPACK_ALIGNMENT, KTX_GL_UNPACK_ALIGNMENT);
943:     }
